            receipt["safe_native_error"] = safe_native_error(wire, self.redactions)
            raise NativeError(wire)
        result = wire["structuredContent"] if "structuredContent" in wire else json.loads("\n".join(c["text"] for c in wire["content"] if c["type"] == "text"))
        if isinstance(result, dict):
            identity = {}
            if result.get("brain_id") == self.brain_id:
                identity["brain_id"] = result["brain_id"]
            if isinstance(result.get("memory_id"), str) and re.fullmatch(r"[0-9]+", result["memory_id"]):
                identity["memory_id"] = result["memory_id"]
            if type(result.get("revision")) is int and result["revision"] > 0:
                identity["revision"] = result["revision"]
            receipt["native_identity"] = identity
        return result

    def remember(self, collection, record, *, provenance=None):
